/* sudoers.c (simplified) */
static int set_cmnd(char **argv, int shell_mode)
{
    char *to, *from, **av;
    size_t size;
    char *user_args;

    /* room for every argument plus one separator each */
    size = 0;
    for (av = argv + 1; *av != NULL; av++)
        size += strlen(*av) + 1;
    if (size == 0 || (user_args = malloc(size)) == NULL)
        return -1;

    if (shell_mode) {
        /* unescape characters the shell would otherwise consume */
        to = user_args;
        for (av = argv + 1; (from = *av) != NULL; av++) {
            while (*from) {
                if (from[0] == '\\' && !isspace((unsigned char)from[1]))
                    from++;
                *to++ = *from++;
            }
            *to++ = ' ';
        }
        *--to = '\0';
    }
    user_cmnd_args = user_args;
    return 0;
}
